def match(orders):
    buy_book = []  # List of [price, arrival_time, id, remaining_qty]
    sell_book = []  # List of [price, arrival_time, id, remaining_qty]
    trades = []
    arrival_time = 0
    id_to_order = {}  # Maps id to (side, index_in_book) for tracking resting orders

    for order in orders:
        arrival_time += 1
        order_type = order[0]

        if order_type == 'cancel':
            order_id = order[1]
            if order_id in id_to_order:
                side, idx = id_to_order[order_id]
                book = buy_book if side == 'buy' else sell_book
                if idx < len(book) and book[idx][2] == order_id:
                    book[idx] = None
                del id_to_order[order_id]

        else:
            order_id = order[1]
            side = order[2]

            if order_type == 'market':
                price = None
                qty = order[3]
            else:
                price = order[3]
                qty = order[4]

            incoming_qty = qty

            if side == 'buy':
                resting_book = sell_book
                incoming_book = buy_book
            else:
                resting_book = buy_book
                incoming_book = sell_book

            # Match against resting orders
            i = 0
            while i < len(resting_book) and incoming_qty > 0:
                resting_order = resting_book[i]

                if resting_order is None:
                    i += 1
                    continue

                resting_price, resting_arrival, resting_id, resting_qty = resting_order

                # Check if match should happen
                should_match = False
                if side == 'buy' and (price is None or price >= resting_price):
                    should_match = True
                elif side == 'sell' and (price is None or price <= resting_price):
                    should_match = True

                if not should_match:
                    break

                # Execute trade
                trade_qty = min(incoming_qty, resting_qty)
                if side == 'buy':
                    trades.append([order_id, resting_id, resting_price, trade_qty])
                else:
                    trades.append([resting_id, order_id, resting_price, trade_qty])

                incoming_qty -= trade_qty
                resting_qty -= trade_qty

                if resting_qty == 0:
                    resting_book[i] = None
                    del id_to_order[resting_id]
                else:
                    resting_book[i] = (resting_price, resting_arrival, resting_id, resting_qty)

                i += 1

            # Add remaining quantity to book if it's a limit order
            if (order_type == 'limit' or order_type == 'market') and incoming_qty > 0:
                if order_type == 'limit':
                    incoming_book.append([price, arrival_time, order_id, incoming_qty])
                    id_to_order[order_id] = (side, len(incoming_book) - 1)
            elif order_type == 'limit':
                # Fully filled limit order
                id_to_order[order_id] = (side, -1)

    return trades

